param([Parameter(Mandatory=$true)][int]$ProcessId,[int]$Port=37672,[string]$JdkHome='C:\Program Files\Eclipse Adoptium\jdk-21.0.11.10-hotspot')
$ErrorActionPreference='Stop';$ProjectRoot=Split-Path -Parent $PSScriptRoot;$Jar=&(Join-Path $PSScriptRoot 'build-telemetry-agent.ps1') -JdkHome $JdkHome;$Attach=Get-ChildItem (Join-Path $ProjectRoot 'analysis\packet-agent-build') -Filter 'packet-agent-*.jar'|Sort-Object LastWriteTime -Descending|Select-Object -First 1 -ExpandProperty FullName;$Log=Join-Path $ProjectRoot 'captures\telemetry-agent.log';&(Join-Path $JdkHome 'bin\java.exe') --add-modules jdk.attach -cp $Attach lab.agent.AttachPacketAgent $ProcessId $Jar "$Log,$Port,$((Get-Date).ToString('yyyyMMddHHmmssfff'))";if($LASTEXITCODE-ne 0){throw 'attach failed'};"Telemetry agent attached pid=$ProcessId port=$Port"
